#include <bits/stdc++.h>
using namespace std;

using ll = long long;

void solve() {
    int n, c; cin >> n >> c;
    vector<int> perm(n), cost(n);
    for (auto &x : perm) {
        cin >> x;
        x--;
    }
    for (auto &x : cost)
        cin >> x;
    ll ans = 0;
    vector<bool> viz(n);
    for (int i = 0; i < n; i++) {
        if (viz[i])
            continue;
        ll curr = 0, mx = 0;
        int run = i;
        vector<int> cc;
        while (!viz[run]) {
            cc.push_back(cost[run]);
            viz[run] = true;
            run = perm[run];
        }
        sort(cc.begin(), cc.end());
        while (cc.size() > 1) {
            curr -= c;
            curr += cc.back();
            cc.pop_back();
            mx = max(mx, curr);
        }
        curr += cc[0];
        mx = max(mx, curr);
        ans += mx;
    }
    cout << ans;
}

int main() {
	int T; cin >> T;
	while (T--) {
	    solve();
	    cout << "\n";
	}

}
